/-- Endpoint-regularized Jacobi weight at the public spectral degree. -/
def jacobiRegularizedWeight (a b : ℝ) (m : ℕ) (x : ℝ) : ℝ :=
  (1-x+(m : ℝ)^(-2 : ℝ))^(a+1/2) * (1+x+(m : ℝ)^(-2 : ℝ))^(b+1/2)

/-- Squared Lebesgue norm of the standard Jacobi polynomial under its Jacobi weight. -/
def jacobiSqNorm (a b : ℝ) (j : ℕ) : ℝ :=
  ∫ z in Icc (-1 : ℝ) 1, jacobiWeight a b z * (stdJacobi a b j z)^2

/-- Unmarked and potential-mean-marked conditional latent measures used in identification. -/
def latentDoseLaw (P : Measure (StructSpace S)) (x : Bool) : Measure ℝ :=
  (stratumLaw P x).map latentCentered

/-- Conditional latent dose measure marked by the conditional potential-outcome mean. -/
def latentMeanMeasure (E : PathSpace S) (P : Measure (StructSpace S)) (x : Bool) : Measure ℝ :=
  (latentDoseLaw P x).withDensity (fun t => ENNReal.ofReal (condPotMean E P x (t+a0)))

/-- Population localized marked-to-unmarked ratio. -/
def localizedRatio (sigma : ℝ) (P : Measure (StructSpace S)) (x : Bool) (q : WeightPair) : ℝ :=
  populationM sigma P x q / populationD sigma P x q -- @realizes mxq(population marked/unmarked ratio)

