/-- Probability laws satisfying exactly the bounded noisy-dose causal model assumptions. -/
def modelClass (E : PathSpace S) (K : ClassConstants) (beta kappa sigma : ℝ) : Set (ProbabilityMeasure (StructSpace S)) := -- @realizes P(probability-law carrier on structural coordinates)
  {P | NoisyDoseModelClass E K beta kappa sigma (P : Measure (StructSpace S))} -- @realizes Pclass(probability laws satisfying the ten assumptions)

/-- Factorial tail in the observed Gaussian moment-series comparison. -/
def momentTail (sigma ell : ℝ) (J : ℕ) : ℝ :=
  ∑' j : ℕ, if J ≤ j then (ell^2/sigma^2)^j/(j.factorial : ℝ) else 0

/-- Empirical stratum ratio with the public denominator floor and projection to the unit outcome interval. -/
def muhat (K : ClassConstants) (kappa : ℝ) (n : ℕ) (data : Fin n → Obs) (x : Bool) (q : WeightPair) : ℝ :=
  max 0 (min 1 (Mhat n data x q / max (Dhat n data x q) (bq K kappa q.q/2))) -- @realizes muhatx(public floor followed by projection)

